CREATE TABLE IF NOT EXISTS `user_histories` (
  `id` int NOT NULL,
  `resumen` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Resumen',
  `issueCve` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Clave de incidencia',
  `issueId` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ID de la incidencia',
  `issueType` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Tipo de Incidencia',
  `state` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Estado',
  `projectId` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Clave del proyecto',
  `nombredelproyecto` varchar(100) DEFAULT NULL COMMENT 'Nombre del proyecto',
  `proyectoType` varchar(100) DEFAULT NULL COMMENT 'Tipo de proyecto',
  `priority` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Prioridad',
  `resolucion` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Resolución',
  `assignPerson` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Persona asignada',
  `informador` varchar(100) DEFAULT NULL COMMENT 'Informador',
  `createPerson` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Creador',
  `createdDate` datetime NOT NULL COMMENT 'Creada',
  `lastModified` datetime NOT NULL COMMENT 'Actualizada',
  `lastview` datetime NOT NULL COMMENT 'Vista por Última Vez',
  `finalizeddate` datetime DEFAULT NULL COMMENT 'Resuelta',
  `fixedversion` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Versiones corregidas',
  `component` json DEFAULT NULL COMMENT 'Componentes',
  `expirationDate` datetime DEFAULT NULL COMMENT 'Fecha de vencimiento',
  `etiquetas` json CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Etiquetas',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT 'Descripción',
  `envioroments` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Entorno',
  `interestedPersons` json DEFAULT NULL COMMENT 'Interesados',
  `originalEstimation` json DEFAULT NULL COMMENT 'Estimación original',
  `estimatedRemainingWork` json DEFAULT NULL COMMENT 'Trabajo restante estimado',
  `jobTime` json DEFAULT NULL COMMENT 'Tiempo Trabajado',
  `issuelinkinternal` json DEFAULT NULL COMMENT 'Enlace a la incidencia interna (Blocks)',
  `issuelinkoutgoing` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Blocks)',
  `issuelinkinternalcloner` json DEFAULT NULL COMMENT 'Enlace a la incidencia interna (Cloners)',
  `issuelinkoutgoingcloner` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Cloners)',
  `issuelinkoutgoinduplicate` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Duplicate)',
  `issuelinkinternalissuesplit` json DEFAULT NULL COMMENT 'Enlace a la incidencia interna (Issue split)',
  `issuelinkoutgoingissuesplit` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Issue split)',
  `issuelinkinternalproblem` json DEFAULT NULL COMMENT 'Enlace a la incidencia interna (Problem/Incident)',
  `issuelinkoutgoingproblem` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Problem/Incident)',
  `issuelinkinternalrelates` json DEFAULT NULL COMMENT 'Enlace a la incidencia interna (Relates)',
  `issuelinkoutgoingrelates` json DEFAULT NULL COMMENT 'Enlace de incidencia saliente (Relates)',
  `attachments` json DEFAULT NULL COMMENT 'Adjunto',
  `dor` decimal(10,0) DEFAULT NULL COMMENT 'Campo personalizado (% DoR)',
  `ambiente` json DEFAULT NULL COMMENT 'Campo personalizado (Ambiente)',
  `assigneeqa` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Assignee QA)',
  `businessdata` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Business Data)',
  `businessdatadate` datetime CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Business Data Date)',
  `businessidea` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Business Idea)',
  `po` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Business PO)',
  `canal` json DEFAULT NULL COMMENT 'Campo personalizado (Canal)',
  `cardtype` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Campo personalizado (Card Type)',
  `carryover` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Carry Over)',
  `carryoverdetail` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Carry Over Detail)',
  `carryoverdesviation` int DEFAULT NULL COMMENT 'Campo personalizado (Carry Over Deviation)',
  `carryoverrecoverytime` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Carry Over Recovery Time)',
  `causeoferrer` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Cause of error)',
  `codeQuality` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Code_quality)',
  `codingstartdate` datetime DEFAULT NULL COMMENT 'Campo personalizado (Coding start date)',
  PRIMARY KEY (`id`),
  KEY `userhistories_issueId_IDX` (`issueId`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `user_histories2` (
