  `issueCve` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Clave de incidencia',
  `complejidad` int DEFAULT NULL COMMENT 'Campo personalizado (Complejidad)',
  `componentsdor` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Components)',
  `componentsdordate` datetime DEFAULT NULL COMMENT 'Campo personalizado (Components Date)',
  `comprometida` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Comprometida)',
  `criteriaofacceptance` datetime DEFAULT NULL COMMENT 'Campo personalizado (Criteria of Acceptance Date)',
  `criteriaofacceptance` varchar(100) DEFAULT NULL COMMENT 'Campo personalizado (Criteria of acceptance)',
